1\\u043a\\u0438\\u0435 \\u043a\\u043b\\u0430\\u0441\\u0441\\u044b \\u0438 \\u0431\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0438\\n\\n**3.1. \\u0421\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u043a\\u0430 \\u2014 6 \\u043a\\u043b\\u0430\\u0441\\u0441\\u043e\\u0432**, \\u226520 \\u0441\\u0435\\u0440\\u0438\\u0439 \\u043d\\u0430 \\u043a\\u043b\\u0430\\u0441\\u0441, \\u22653 \\u0444\\u043e\\u043b\\u0434\\u0430 (\\u0438\\u0442\\u043e\\u0433\\u043e \\u2265360 (\\u0441\\u0435\\u0440\\u0438\\u044f*\\u0444\\u043e\\u043b\\u0434)):\\n\\n(1) Single-tone: \\u0441\\u0438\\u043d\\u0443\\u0441\\u043e\\u0438\\u0434\\u0430 + AR(1) \\u0448\\u0443\\u043c, \\u03c9_true in {6,12,24,48,96,1440}, N = 8\\u00b7\\u03c9_true. \\u0411\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439.\\n\\n(2) Two-tone: \\u0441\\u0443\\u043c\\u043c\\u0430 \\u0434\\u0432\\u0443\\u0445 \\u0441\\u0438\\u043d\\u0443\\u0441\\u043e\\u0438\\u0434 + AR(1) \\u0448\\u0443\\u043c; \\u043f\\u0430\\u0440\\u044b (24,48), (96,1440) \\u0441\\u043e-\\u043f\\u0440\\u044f\\u043c., (24,96), (48,1440) \\u043d\\u0435\\u0441\\u043e-\\u043f\\u0440\\u044f\\u043c. N = 8\\u00b7max(\\u03c9\\u2081, \\u03c9\\u2082). \\u041f\\u043e\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 U5.\\n\\n(3) AM: \\u043d\\u0435\\u0441\\u0443\\u0449\\u0430\\u044f \\u03c9_c in {6,24,96}, \\u043e\\u0433\\u0438\\u0431\\u0430\\u044e\\u0449\\u0430\\u044f \\u03c9_e = 3\\u00b7\\u03c9_c, N = 8\\u00b7\\u03c9_e. \\u0427\\u0430\\u0441\\u0442\\u043e\\u0442\\u043d\\u043e-\\u0440\\u0430\\u0437\\u0440\\u0435\\u0448\\u0430\\u044e\\u0449\\u0438\\u0439 \\u0442\\u0435\\u0441\\u0442; U5.\\n\\n(4) \\u0422\\u0440\\u0435\\u043d\\u0434+\\u0441\\u0435\\u0437\\u043e\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c: \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0439/\\u043a\\u0443\\u0441\\u043e\\u0447\\u043d\\u043e-\\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0439 \\u0442\\u0440\\u0435\\u043d\\u0434 + \\u0441\\u0435\\u0437\\u043e\\u043d \\u03c9_s in {24,96,1440}, N = 8\\u00b7\\u03c9_s. \\u041a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e \\u0434\\u0435\\u0442\\u0440\\u0435\\u043d\\u0434\\u0438\\u043d\\u0433\\u0430.\\n\\n(5) AR(p)-\\u0448\\u0443\\u043c: \\u0447\\u0438\\u0441\\u0442\\u044b\\u0439 AR(2) \\u0438\\u043b\\u0438 AR(4), \\u03c9_true = 1, N = 4096 \\u0444\\u0438\\u043a\\u0441. FPR-\\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c.\\n\\n(6) \\u041a\\u0432\\u0430\\u0437\\u0438-\\u0441\\u0435\\u0437\\u043e\\u043d \\u0441 \\u0444\\u0430\\u0437\\u043e\\u0432\\u044b\\u043c \\u0434\\u0440\\u0435\\u0439\\u0444\\u043e\\u043c: \\u03c9_q in {24,96} + \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0439 \\u0434\\u0440\\u0435\\u0439\\u0444 \\u0444\\u0430\\u0437\\u044b 1\\u20135% \\u043e\\u0442 N, N = 16\\u00b7\\u03c9_q. U4, U5.\\n\\n\\u041f\\u043e\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435 U5: \\u043a\\u043b\\u0430\\u0441\\u0441\\u044b 2 (\\u044f\\u0432\\u043d\\u0430\\u044f \\u043c\\u0443\\u043b\\u044c\\u0442\\u0438-\\u0441\\u0435\\u0437\\u043e\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c), 3 (\\u043c\\u043e\\u0434\\u0443\\u043b\\u044f\\u0446\\u0438\\u044f), 6 (\\u0434\\u0440\\u0435\\u0439\\u0444 \\u0444\\u0430\\u0437\\u044b).\\n\\n**3.2. \\u0411\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0438 (4 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u0430)**: ETTh1, ETTm1, Weather, Electricity.\\n\\n\\u0423\\u0434\\u0430\\u043b\\u0435\\u043d\\u044b: Traffic (\\u043d\\u0435\\u0447\\u0451\\u0442\\u043a\\u0430\\u044f \\u0441\\u0443\\u0442\\u043e\\u0447\\u043d\\u0430\\u044f \\u0441\\u0435\\u0437\\u043e\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c, \\u043d\\u0435\\u0442 \\u043e\\u0434\\u043d\\u043e\\u0437\\u043d\\u0430\\u0447\\u043d\\u043e\\u0433\\u043e \\u03c9) \\u0438 Exchange (\\u0434\\u043d\\u0435\\u0432\\u043d\\u043e\\u0439, \\u0431\\u0435\\u0437\\u043d\\u0430\\u0434\\u0451\\u0436\\u043d\\u043e \\u0437\\u0430\\u0448\\u0443\\u043c\\u043b\\u0451\\u043d \\u2014 \\u0437\\u0434\\u0435\\u0441\\u044c \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c \\u03c9 = 1, \\u0447\\u0442\\u043e \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0434\\u0438\\u0442 \\u043d\\u0443\\u043b\\u0435\\u0432\\u0443\\u044e \\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u0443 \\u0438 \\u0432\\u0430\\u043b\\u0438\\u0434\\u0438\\u0440\\u0443\\u0435\\u0442 \\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u044b \\u00ab\\u043d\\u0430 \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0438\\u0435 \\u0441\\u0435\\u0437\\u043e\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438\\u00bb).\\n\\n---\\n\\n### 4. \\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b \\u0440\\u0430\\u0437\\u0431\\u0438\\u0435\\u043d\\u0438\\u044f \\u0441 \\u0437\\u0430\\u0449\\u0438\\u0442\\u043e\\u0439 \\u043e\\u0442 \\u0443\\u0442\\u0435\\u0447\\u043a\\u0438\\n\\n**4.1. \\u0421\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0430** (\\u0445\\u0440\\u043e\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438, \\u0431\\u0435\\u0437 \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f): train (60%), val (20%), test (20%); N_test \\u2265 2\\u00b7H.\\n\\n**4.2. \\u041f\\u0440\\u0430\\u0432\\u0438\\u043b\\u0430 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u0430:**\\n- \\u0414\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u044b A\\u2013D \\u0438 diagnose-\\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u043e\\u043f\\u0435\\u0440\\u0438\\u0440\\u0443\\u044e\\u0442 \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u043d\\u0430 train-\\u043e\\u043a\\u043d\\u0435.\\n- val \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0434\\u043b\\u044f \\u0440\\u0430\\u043d\\u043d\\u0435\\u0439 \\u043e\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0438.\\n- MSE(\\u03c9) \\u2014 \\u043d\\u0430 test-\\u043e\\u043a\\u043d\\u0435.\\n- K5 (argmin_\\u03c9 MSE) \\u0441\\u0447\\u0438\\u0442\\u0430\\u0435\\u0442\\u0441\\u044f \\u043d\\u0430 val, \\u043d\\u0435 \\u043d\\u0430 test, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043d\\u0435 \\u0431\\u044b\\u043b\\u043e look-ahead.\\n\\n**4.3. Smoke-\\u0442\\u0435\\u0441\\u0442 \\u043d\\u0430 \\u0443\\u0442\\u0435\\u0447\\u043a\\u0443 (LEAK-\\u0442\\u0435\\u0441\\u0442):** \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0430 \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0441\\u0435\\u0440\\u0438\\u0438 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0442\\u044c \\u03c9_train \\u0438 \\u03c9_train\\u222aval; \\u0441\\u0438\\u0441\\u0442\\u0435\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u0440\\u0430\\u0441\\u0445\\u043e\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 > 50% \\u0441\\u0435\\u0440\\u0438\\u0439 \\u2014 \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b \\u0443\\u0442\\u0435\\u0447\\u043a\\u0438 \\u0432 \\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0435. \\u0420\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0432 D4.\\n\\n---\\n\\n### 5. \\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u0438 \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438\\n\\n**5.1. \\u041f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u044b\\u0435:** MSE(\\u03c9), MAE(\\u03c9) \\u043d\\u0430 test-\\u043e\\u043a\\u043d\\u0435; \\u043f\\u0440\\u0438 H in {1, \\u03c9, 2\\u03c9}.\\n\\n**5.2. \\u041a\\u043e\\u043c\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u044b \\u041f\\u0430\\u0440\\u0435\\u0442\\u043e-score** (\\u0434\\u043b\\u044f d in {A,B,C,D} \\u043d\\u0430 \\u0441\\u0435\\u0440\\u0438\\u0438 s, \\u0444\\u043e\\u043b\\u0434\\u0435 f):\\n\\n- \\u0394_mse(d,s,f) = MSE(\\u03c9_d) \\u2212 min_\\u03c9 MSE(\\u03c9); \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e\\u043f\\u0435\\u0440\\u0441\\u0451\\u0440\\u043d\\u043e\\u0441\\u043d\\u043e: \\u0394_mse_norm = \\u0394_mse / (\\u0394_mse_max_per_series + \\u03b5), \\u03b5 = 10\\u207b\\u2076.\\n- \\u03c3(d,s) = std_f MSE(\\u03c9_d); \\u03c3_norm = \\u03c3 / (\\u03c3_max_per_series + \\u03b5).\\n- \\u0394_robust(d,s) = median_{\\u03c3, shift} (MSE_NOISY \\u2212 MSE_CLEAN) / MSE_CLEAN \\u043f\\u043e \\u0441\\u0435\\u0442\\u043a\\u0435 U4; \\u0394_robust_norm \\u043d\\u043e\\u0440\\u043c\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e\\u043f\\u0435\\u0440\\u0441\\u0451\\u0440\\u043d\\u043e\\u0441\\u043d\\u043e.\\n\\n**5.3. Score \\u0438 argmin:**\\n\\nScore(d, s) = \\u0394_mse_norm + \\u03c3_norm + \\u0394_robust_norm (\\u0440\\u0430\\u0432\\u043d\\u044b\\u0435 \\u0432\\u0435\\u0441\\u0430 1/3).\\ndetector_argmin(s) = argmin_d Score(d, s).\\n\\n\\u0410\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 \\u0432\\u0435\\u0441\\u0430 \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u044e\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a robustness; \\u0441\\u043c. D4.\\n\\n**5.4. \\u0410\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442\\u044b:**\\n- Top-1 accuracy (\\u0441\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u043a\\u0430): \\u0434\\u043e\\u043b\\u044f \\u0441\\u0435\\u0440\\u0438\\u0439, \\u043d\\u0430 \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0445 detector_argmin(s) \\u0441\\u043e\\u0432\\u043f\\u0430\\u043b \\u0441 argmin_d MSE(\\u03c9_d) \\u043d\\u0430 \\u0442\\u043e\\u0439 \\u0436\\u0435 \\u0441\\u0435\\u0440\\u0438\\u0438 (\\u043f\\u043e\\u043f\\u0430\\u0440\\u043d\\u043e \\u043f\\u043e \\u0441\\u0435\\u0440\\u0438\\u0438).\\n- \\u0421\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 \\u0440\\u0430\\u043d\\u0433 1..4.\\n- \\u0420\\u0430\\u0437\\u0440\\u044b\\u0432 \\u0441 \\u043e\\u0440\\u0430\\u043a\\u0443\\u043b\\u043e\\u043c: MSE(\\u03c9_d) / MSE(\\u03c9_oracle_test), \\u0433\\u0434\\u0435 \\u03c9_oracle_test = argmin_\\u03c9 MSE(\\u03c9) \\u043d\\u0430 test (\\u043e\\u043f\\u0438\\u0441\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e, \\u043d\\u0435 \\u043a\\u0430\\u043a \\u0432\\u0445\\u043e\\u0434).\\n\\n**5.5. \\u041e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435 `robust` (\\u043e\\u0434\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0440\\u043e\\u043a\\u043e\\u0439):**\\n\\nrobust_score(d,s) = \\u043c\\u0435\\u0434\\u0438\\u0430\\u043d\\u043d\\u043e\\u0435 \\u043e\\u0442\\u043d\\u043e\\u0441\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0438\\u0437\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u0435 MSE(\\u03c9_d) \\u043d\\u0430 \\u0442\\u0435\\u0441\\u0442\\u0435 \\u043f\\u0440\\u0438 \\u0438\\u043d\\u0436\\u0435\\u043a\\u0446\\u0438\\u0438 (\\u03c3_noise, phase_shift) \\u0438\\u0437 U4 \\u043e\\u0442\\u043d\\u043e\\u0441\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e MSE(\\u03c9_d) \\u043d\\u0430 \\u0447\\u0438\\u0441\\u0442\\u043e\\u043c \\u0441\\u0438\\u0433\\u043d\\u0430\\u043b\\u0435.\\n\\n---\\n\\n### 6. \\u041f\\u043b\\u0430\\u043d \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430\\n\\n1. \\u0414\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e (\\u0441\\u0435\\u0440\\u0438\\u044f, \\u0444\\u043e\\u043b\\u0434) \\u043f\\u043e\\u0441\\u0442\\u0440\\u043e\\u0438\\u0442\\u044c MSE(\\u03c9) \\u043f\\u043e \\u043f\\u043e\\u043b\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0435 [1, T]; \\u043f\\u043e\\u043c\\u0435\\u0442\\u0438\\u0442\\u044c A\\u2013D \\u0438 K1\\u2013K6.\\n2. \\u0421\\u0432\\u043e\\u0434\\u043d\\u0430\\u044f \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430 (4 \\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u0430 \\u00d7 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442 \\u00d7 \\u0444\\u043e\\u043b\\u0434) \\u2192 (\\u0394, \\u0440\\u0430\\u043d\\u0433, \\u0441\\u0442\\u0430\\u0431\\u0438\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c, robust_score); \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 mean \\u00b1 std.\\n3. Score(d, s) \\u0438 detector_argmin(s) \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0441\\u0435\\u0440\\u0438\\u0438.\\n4. \\u041f\\u043e\\u043f\\u0430\\u0440\\u043d\\u043e\\u0435 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 4 \\u0434\\u0435\\u0442\\u0435\\u043a\\u0442\\u043e\\u0440\\u043e\\u0432 \\u043f\\u043e Score \\u2014 Wilcoxon \\u043f\\u043e \\u0441\\u0435\\u0440\\u0438\\u044f\\u043c.\\n5. Top-1 accuracy \\u0434\\u043b\\u044f \\u0441\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u043a\\u0438 (per-series) \\u0438 \\u0441\\u0440\\u0435\\u0434\\u043d\\u0438\\u0439 \\u0440\\u0430\\u043d\\u0433 (1..4).\\n6. Scatter: \\u03c9_detector vs \\u03c9_true (\\u0441\\u0438\\u043d\\u0442\\u0435\\u0442\\u0438\\u043a\\u0430) \\u0438 \\u03c9_detector vs \\u03c9_argmin_val (\\u0432\\u0441\\u0435 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0435).\\n7. LEAK-\\u0442\\u0435\\u0441\\u0442; \\u0432\\u043d\\u0435\\u0441\\u0442\\u0438 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u0432 D4.\\n8. Diagnose-\\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 (PACF, ACF-residuals, robust-lags) \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0435\\u0441\\u043b\\u0438 A\\u2013D \\u0434\\u0430\\u043b\\u0438 \\u043d\\u0435\\u043e\\u0434\\u043d\\u043e\\u0437\\u043d\\u0430\\u0447\\u043d\\u044b\\u0439 \\u043e\\u0442\\u0432\\u0435\\u0442 \\u043d\\u0430 \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u043e\\u043c \\u043a\\u043b\\u0430\\u0441\\u0441\\u0435.\\n9. \\u0421\\u0444\\u043e\\u0440\\u043c\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c D1\\u2013D4 (\\u0441\\u043c. \\u043f. 7).\\n\\n---\\n\\n### 7. \\u0428\\u0430\\u0431\\u043b\\u043e\\u043d\\u044b \\u0432\\u044b\\u0445\\u043e\\u0434\\u043d\\u044b\\u0445 \\u0430